import{_ as t,o,c as a,ag as s}from"./chunks/framework.2EHAL5nC.js";const m=JSON.parse('{"title":"Release notes","description":"","frontmatter":{},"headers":[],"relativePath":"release-notes.md","filePath":"release-notes.md","lastUpdated":1794896270000}'),r={name:"release-notes.md"};function i(n,e,d,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="release-notes" tabindex="-1">Release notes <a class="header-anchor" href="#release-notes" aria-label="Permalink to &quot;Release notes&quot;">​</a></h1><p>RustCMS is in pre-release. The current version is <strong>0.13.0</strong>; 0.1.0-alpha.0 was the first published one.</p><h2 id="0130" tabindex="-1">0.13.0 <a class="header-anchor" href="#0130" aria-label="Permalink to &quot;0.13.0&quot;">​</a></h2><p>Read the <a href="./upgrade.html#from-0121-to-0130">upgrade guide</a> first: new schema vocabulary, a few Rust API additions, and <code>lock_parent</code> may not target the media library. No migration. Most of this release was contributed by @giangittb112000.</p><ul><li><strong>Number bounds</strong>: <code>NumberInput::make(…).min(n).max(n).step(n)</code> (and on integer settings), checked by the server on every write (<a href="./admin/forms.html#number-bounds">Forms</a>).</li><li><strong>Inputs shown under conditions</strong>: <code>.shown_when(when(&quot;x&quot;).eq(v))</code> on inputs, layouts, tabs, settings and action forms, evaluated live in the panel and again by the server on what the user&#39;s form holds; <code>.clear_when_hidden()</code> (<a href="./admin/forms.html#showing-inputs-under-conditions">Forms</a>).</li><li><strong>Titles from several fields</strong>: <code>ResourceMeta::title_template(&quot;{name} (grade {grade})&quot;)</code>, searched word by word (<a href="./admin/resources.html">Resources</a>).</li><li><strong>Infolists</strong>: <code>infolist()</code> shows a record&#39;s view page with entries (text, badges, relations, media, rich text, custom entries), <code>computed()</code> values computed when the page opens, <code>PageView::Infolist</code> for panel pages; SDK <code>ui</code> 3 (<a href="./admin/infolists.html">Infolists</a>).</li><li><strong>Repeaters</strong>: <code>Repeater::make(&quot;faq&quot;).schema(…)</code> stores rows in a JSON column; with <code>.relationship()</code>, the rows are the child records of a has-many relation, edited in the parent&#39;s form (the child locks its parent); count columns <code>count()</code> / <code>counts(&quot;posts&quot;)</code>; row-level history (<a href="./admin/forms.html#repeaters">Forms</a>, <a href="./admin/tables.html#counts">Tables</a>).</li><li><strong><code>rustcms serve --watch</code></strong> (macOS, Linux): rebuilds on changes and replaces the server once the build succeeds; a failed build keeps the running server (<a href="./getting-started/installation.html#rebuilding-on-changes">Installation</a>).</li><li>A create leaving out a column that may not be null answers <code>is required</code> (422) instead of a server error; actions that move records under <code>lock_parent</code> lock the destination parent.</li><li><strong>Security</strong>: bundled SQLite 3.54.1 (RUSTSEC-2026-0459) through a patched sqlx; existing applications add the patch (<a href="./upgrade.html#from-0121-to-0130">upgrade guide</a>). ammonia 4.2.5.</li></ul><h2 id="0121" tabindex="-1">0.12.1 <a class="header-anchor" href="#0121" aria-label="Permalink to &quot;0.12.1&quot;">​</a></h2><ul><li>A new application (<code>rustcms new</code>) passes the <code>cargo fmt --check</code> of its own CI: it gets a <code>rustfmt.toml</code>, whatever its name (<a href="./getting-started/directory-structure.html">Directory structure</a>).</li></ul><h2 id="0120" tabindex="-1">0.12.0 <a class="header-anchor" href="#0120" aria-label="Permalink to &quot;0.12.0&quot;">​</a></h2><p>Read the <a href="./upgrade.html#from-0110-to-0120">upgrade guide</a> first: the media and exports cleanups now need the scheduler. No migration.</p><ul><li><strong>API mode</strong>: <code>rustcms serve --api-only</code> (or <code>[app] mode = &quot;api&quot;</code>) serves the application API alone, without the admin panel, to scale it out behind a load balancer; the same build runs the panel instance (<a href="./digging-deeper/instances.html#api-mode">API mode</a>).</li><li><strong>Faster API tokens</strong>: a personal access token is checked with one statement, and its last use is written at most once a minute. Two opt-in settings let API instances reuse the permission counter and JWT sign-ins for a short time (<a href="./security/revocation.html#several-instances">Credential revocation</a>).</li><li><strong>Media hooks</strong>: <code>AdminProvider::media_hook</code> runs your code in the transaction of every upload, edit, trash, restore and delete of a media file (<a href="./admin/media.html#media-hooks">Media hooks</a>).</li><li><strong>Cleanups are schedules</strong>: the media and exports cleanups run as <code>rustcms.media-prune.&lt;disk&gt;</code> and <code>rustcms.exports-prune.&lt;disk&gt;</code>; every <code>serve</code> and <code>queue:work</code> removes the temporary files it left (<a href="./operations/retention.html">Data retention</a>).</li><li>Abandoned export and import files on an S3 disk&#39;s staging directory are removed too.</li></ul><h2 id="0110" tabindex="-1">0.11.0 <a class="header-anchor" href="#0110" aria-label="Permalink to &quot;0.11.0&quot;">​</a></h2><p>Read the <a href="./upgrade.html#from-0103-to-0110">upgrade guide</a> first: static select and checkbox options are now enforced, and some form declarations stop the boot. No migration.</p><ul><li><strong>A new guide</strong>: rewritten from the source, with screenshots and samples from compiled examples, on VitePress (search, dark mode, phones). <code>rustcms docs</code> opens the online guide of your version.</li><li><strong>Options are validated</strong>: a client write outside a <code>SelectInput</code>&#39;s or <code>CheckboxList</code>&#39;s options is a 422; a matched value is stored as its option (<a href="./admin/forms.html#options-are-not-validated">Options are validated</a>).</li><li><strong>Framework cleanups are schedules</strong>: the auth and idempotency cleanups run in <code>serve</code> as <code>rustcms.auth-prune</code> and <code>rustcms.idempotency-prune</code>, shown on System → Schedules (<a href="./digging-deeper/scheduling.html#framework-schedules">Framework schedules</a>).</li><li>A panic in a handler answers the standard 500 instead of dropping the connection (<a href="./basics/errors.html">Errors</a>).</li><li>A background export over its limits says why (<code>too_many_to_export</code>, <code>too_many_matches</code>); the export list no longer fails on MySQL with large exports; export and import cleanups only touch their own disk (<a href="./admin/import-export.html">Import and export</a>).</li><li>The panel&#39;s sockets send up to <code>[realtime] max_message_bytes</code> (<a href="./admin/realtime.html">Realtime</a>).</li></ul><h2 id="0103" tabindex="-1">0.10.3 <a class="header-anchor" href="#0103" aria-label="Permalink to &quot;0.10.3&quot;">​</a></h2><ul><li>Record pages on a phone keep the primary action and ⋯ in the header (the other actions, Edit and Delete under ⋯); a viewed text input shows its prefix and suffix (<a href="./admin/actions.html#placement-in-lists">Actions</a>).</li></ul><h2 id="0102" tabindex="-1">0.10.2 <a class="header-anchor" href="#0102" aria-label="Permalink to &quot;0.10.2&quot;">​</a></h2><ul><li><strong>An editor layout</strong>: <code>Form::width(FormWidth::Full)</code>, a main column with a sticky aside (<code>Split</code>), sections that fold or are compact, and text inputs with a fixed prefix or suffix (<code>/posts/</code> before a slug) (<a href="./admin/forms.html#an-editor-layout">An editor layout</a>).</li><li>Badge columns show all five colors; the default theme&#39;s <code>success</code> and <code>warning</code> are green and amber. The media picker keeps a page chosen right after opening.</li></ul><h2 id="0101" tabindex="-1">0.10.1 <a class="header-anchor" href="#0101" aria-label="Permalink to &quot;0.10.1&quot;">​</a></h2><p>Run <code>rustcms migrate</code>; <code>media.update</code> now grants renaming and alt text (see the <a href="./upgrade.html#from-0100-to-0101">upgrade guide</a>).</p><ul><li><strong>Media page</strong>: a grid of thumbnails or the table (remembered per user) and an upload button for several files (<a href="./admin/media.html#the-media-page">The Media page</a>); files can be renamed and given an alternative text, which the editor and the picker pre-fill (<a href="./admin/media.html#names-and-alternative-text">Names and alternative text</a>).</li><li><strong>Media settings</strong>: <code>SettingField::media</code> and <code>media_list</code> (<a href="./admin/settings.html#media-settings">Media settings</a>).</li><li><strong>Actions per record</strong>: <code>Action::visible_when</code>, <code>primary</code> and <code>destructive</code>; list rows show one labelled action and a ⋯ menu, and record pages and relation tables show their actions too (<a href="./admin/actions.html#per-record-visibility">Per-record visibility</a>).</li><li><strong>Action outcomes</strong>: <code>Action::with_outcome</code> returns a message and a page to open in a new tab (<a href="./admin/actions.html#outcomes-a-message-a-page-to-open">Outcomes</a>).</li><li><strong>Narrow screens</strong>: <code>TableColumn::hide_below(Breakpoint::Md)</code> (<a href="./admin/tables.html#narrow-screens">Narrow screens</a>).</li><li>Fixes: bulk actions are offered on rows too; action dialogs are titled without &quot;…&quot; and their button is the action&#39;s label (<code>submit_label</code>); record pages format dates and times; the recent-records widget shows labels and dates; files that cannot be loaded show &quot;File unavailable&quot;; empty values read &quot;Not set&quot;; navigation keeps the registration order.</li></ul><h2 id="0100" tabindex="-1">0.10.0 <a class="header-anchor" href="#0100" aria-label="Permalink to &quot;0.10.0&quot;">​</a></h2><ul><li><strong>Rich text version 2</strong>: tables, YouTube/Vimeo embeds, callouts, image captions and widths; version 1 documents are read as they are (<a href="./admin/media.html#rich-text">Rich text</a>).</li><li><strong>Editor</strong>: several images uploaded at once (choose, drop, paste) with per-file status and retry; a media library picker shared with <code>FileUpload</code> fields (<a href="./admin/media.html#the-media-library-picker">The media library picker</a>).</li><li><strong>Headless HTML</strong>: images as figures with their size (<code>rich_text::to_html_with</code>), stable heading ids with Vietnamese diacritics folded, and <code>rich_text::outline</code> for a table of contents (<a href="./admin/media.html#headless-rendering">Headless rendering</a>).</li></ul><h2 id="090" tabindex="-1">0.9.0 <a class="header-anchor" href="#090" aria-label="Permalink to &quot;0.9.0&quot;">​</a></h2><ul><li><strong><code>Resource::after_trash</code> and <code>after_restore</code></strong> run in the transaction of a trashing and of a restore, with the record; the default <code>after_restore</code> calls <code>after_save</code>, as restores did (<a href="./admin/resources.html#hooks">Resources</a>).</li><li><strong><code>ActionField::datetime</code></strong>: a date and time in an action&#39;s form, entered in UTC (<a href="./admin/actions.html">Actions</a>).</li><li><strong><code>SettingsPage::after_save</code></strong> runs in the save&#39;s transaction with the old and new values (<a href="./admin/settings.html#reacting-to-a-save">Settings</a>).</li><li><strong><code>media.view_all</code></strong>: see and use every file of the media library without the right to remove other users&#39; files (<a href="./admin/media.html#whose-files-a-user-sees">Media</a>).</li><li><strong><code>Resource::after_relation_change</code></strong> runs when links of a belongs-to-many relation change, in the same transaction (<a href="./admin/relationships.html#reacting-to-link-changes">Relationships</a>).</li><li><strong>Links in the record&#39;s form</strong>: <code>BelongsToManySelect::make(&quot;tags&quot;)</code> lets users choose belongs-to-many links while creating or editing a record, with the relation manager&#39;s permissions (<a href="./admin/relationships.html#choosing-links-in-the-records-form">Relationships</a>).</li><li>Rich text links are edited in a dialog; record forms ask before leaving with unsaved changes (<a href="./admin/forms.html#leaving-with-unsaved-changes">Forms</a>).</li><li>Security: <code>tokio</code> 1.53.3 and <code>ctutils</code> 0.4.4 (RUSTSEC-2026-0386, 0385). Applications pinning their own <code>Cargo.lock</code> should run <code>cargo update -p tokio -p ctutils</code>.</li></ul><h2 id="082" tabindex="-1">0.8.2 <a class="header-anchor" href="#082" aria-label="Permalink to &quot;0.8.2&quot;">​</a></h2><ul><li>React pages: a read still in flight when a sub-path navigation remounts the view is delivered to the new view instead of a &quot;session changed&quot; error (<a href="./admin/react-pages.html">React pages</a>).</li><li>Security: updated TLS certificate verification crates (<code>rustls-webpki</code>, <code>webpki-roots</code>) for RUSTSEC-2026-0381, -0382 and -0383.</li></ul><h2 id="081" tabindex="-1">0.8.1 <a class="header-anchor" href="#081" aria-label="Permalink to &quot;0.8.1&quot;">​</a></h2><ul><li><strong>Rollbacks after migrations</strong>: <code>migrate --allow-newer</code> (or <code>[database] allow_newer_migrations = true</code>) lets an older binary start on a database a newer one migrated, when migrations are additive; <code>migrate:status</code> shows them as <code>Newer</code>; <code>rustcms::db::unknown_migrations</code> lists them (<a href="./getting-started/deployment.html#upgrading">Deployment</a>).</li></ul><h2 id="080" tabindex="-1">0.8.0 <a class="header-anchor" href="#080" aria-label="Permalink to &quot;0.8.0&quot;">​</a></h2><ul><li><strong>Job history on the Queue page</strong>: finished jobs (done, failed, cancelled) with their times and duration, a details dialog, filters by time, auto refresh; <code>Job::describe()</code> names a job (&quot;deploy demo/web #12&quot;); the <em>Scheduled</em> status is now <em>Delayed</em> (<a href="./digging-deeper/queues.html#the-queue-page">Queues</a>).</li><li><strong>System → Schedules</strong>: every schedule, its next and last run and its history, and <strong>Run now</strong> for job and closure schedules (<a href="./digging-deeper/scheduling.html#the-schedules-page">Scheduling</a>).</li><li><strong><code>Resource::after_delete</code></strong> runs in the transaction of a hard delete, for example to dispatch a job that removes what the record configured (<a href="./admin/resources.html">Resources</a>).</li><li><strong><code>.task(…)</code> schedules</strong> report a summary or a safe error; <code>.timeout(…)</code> bounds a closure&#39;s run; <code>Job::AT_MOST_ONCE</code> for jobs that must never run twice.</li></ul><h2 id="071" tabindex="-1">0.7.1 <a class="header-anchor" href="#071" aria-label="Permalink to &quot;0.7.1&quot;">​</a></h2><ul><li><strong>Dialogs have a close button</strong> (×) in their top right corner, also the <code>Dialog</code> of React pages; forms in dialogs cannot be closed while saving.</li></ul><h2 id="070" tabindex="-1">0.7.0 <a class="header-anchor" href="#070" aria-label="Permalink to &quot;0.7.0&quot;">​</a></h2><ul><li><strong>Roles page</strong>: permissions by area (collapsible, with counts), a search box, labels and descriptions, and presets (&quot;Viewer&quot;, &quot;Developer&quot;) as starting selections, declared on the <code>AuthProvider</code> with <code>permission_area</code>, <code>permission_meta</code> and <code>permission_preset</code> (<a href="./security/authorization.html#the-roles-page-areas-labels-and-presets">Roles &amp; permissions</a>).</li><li><strong>Runtime branding</strong>: <code>AdminProvider::branding(source)</code> sets the brand name, logos (light and dark), favicon and theme tokens while the app runs, cached per instance and invalidated at once; <code>[admin] branding = &quot;static&quot;</code> recovers (<a href="./admin/customizing.html#runtime-branding">Runtime branding</a>).</li><li>The sign-in, password reset and invitation pages show the brand name and logo; the brand names the browser tab.</li></ul><h2 id="061" tabindex="-1">0.6.1 <a class="header-anchor" href="#061" aria-label="Permalink to &quot;0.6.1&quot;">​</a></h2><ul><li><strong>Light, Dark or System per user</strong>: a switch at the bottom of the sidebar, kept in the browser; the app&#39;s color scheme stays the default (<a href="./admin/customizing.html#theme">Theme</a>).</li><li>React pages: <code>useColorScheme()</code> to redraw canvas charts in the current scheme (<a href="./admin/react-pages.html#calling-your-routes">React pages</a>).</li></ul><h2 id="060" tabindex="-1">0.6.0 <a class="header-anchor" href="#060" aria-label="Permalink to &quot;0.6.0&quot;">​</a></h2><ul><li><strong>Resources from React pages</strong>: <code>props.resources</code> and the hooks <code>useResource</code> and <code>useResourceMutation</code> read and write your resources through the panel&#39;s routes. Policies, validation, audit and encrypted fields apply; a lost answer pauses writes safely, as in the panel (<a href="./admin/react-pages.html#records-of-your-resources">React pages</a>).</li><li><strong>Toasts</strong>: <code>props.toast.success</code> and <code>props.toast.error</code>.</li><li><strong>Page titles</strong>: <code>props.title(text)</code> names a sub-page in the panel&#39;s heading and breadcrumb (<code>null</code> hides the heading).</li><li><strong>More components</strong>: Tabs, DropdownMenu, Tooltip, Table, Skeleton, Separator and CodeBlock, CSP-safe and usable inside dialogs.</li><li><strong>More icons</strong> for resources and pages.</li><li><strong>Any-of page permissions</strong>: <code>PanelPageMeta::permission_any([…])</code>.</li><li><code>ui: 1</code> React pages keep working; set <code>ui: 2</code> to use the new parts.</li></ul><h2 id="051" tabindex="-1">0.5.1 <a class="header-anchor" href="#051" aria-label="Permalink to &quot;0.5.1&quot;">​</a></h2><ul><li><strong>Home page</strong>: <code>AdminProvider::home(slug)</code> opens one of your pages at <code>/admin</code> (<a href="./admin/overview.html#home-page">Navigation</a>).</li><li><strong>Order</strong>: <code>.sort(n)</code> on resources and pages orders the sidebar.</li><li><strong>Hidden resources</strong>: <code>ResourceMeta::navigation(false)</code> keeps a resource&#39;s routes and API without a sidebar entry.</li></ul><h2 id="050" tabindex="-1">0.5.0 <a class="header-anchor" href="#050" aria-label="Permalink to &quot;0.5.0&quot;">​</a></h2><ul><li><strong>React pages</strong>: a page, slot or cell can be a React component rendered inside the panel, on its React, React Query, UI kit, theme and router (<code>extension_script_v2</code>, <code>rustcms make:page &lt;Name&gt; --react</code>). <ul><li>Props carry the page data, the sub-path, <code>can(permission)</code>, an API client with the session and CSRF token, and realtime streams; hooks <code>useAdminQuery</code>, <code>useAdminMutation</code>, <code>useEvents</code>, <code>useSocket</code>.</li><li>A bundle needing another React or React Query major, a newer minor than the panel&#39;s, or a higher UI level is refused before it runs; a view that throws shows Retry; the CSP is unchanged.</li><li>Built files are committed, so building the app needs no Node (<a href="./admin/react-pages.html">React pages</a>).</li></ul></li><li><strong>Sub-pages</strong>: <code>/admin/p/&lt;slug&gt;/&lt;sub/path&gt;</code> opens the same page, with <code>ctx.page_path()</code> in <code>data</code>.</li><li>Plain script extensions (v1) work as before.</li></ul><h2 id="041" tabindex="-1">0.4.1 <a class="header-anchor" href="#041" aria-label="Permalink to &quot;0.4.1&quot;">​</a></h2><ul><li><strong>Encrypted columns</strong>: <code>rustcms::crypto::Encrypted&lt;T&gt;</code> keeps secrets of your own tables (tokens, environment variables, credentials) sealed with <code>APP_KEY</code>, bound to their table and column. <ul><li>Values are never serialized, logged or deserialized from JSON; you <code>seal</code> and <code>open</code> them explicitly (<a href="./digging-deeper/encryption.html">Encrypted columns</a>).</li></ul></li><li><strong>Key rotation</strong>: <code>APP_PREVIOUS_KEYS</code> keeps old keys for opening only, and <code>rustcms key:reencrypt</code> moves every encrypted column and settings secret to the new key, safely and resumably (<a href="./operations/app-key.html">Rotating APP_KEY</a>).</li><li><strong>Encrypted fields in the panel</strong>: <code>Field::encrypted()</code> (a secret string) and <code>Field::encrypted_map()</code> (named secrets). <ul><li>Write-only: the panel shows names and states, never values.</li><li>Each value is kept, replaced or removed; a save over someone else&#39;s change is refused.</li><li>Always redacted in the audit log (<a href="./admin/forms.html#encrypted-fields">Forms</a>).</li></ul></li><li><strong>Scheduling</strong>: <code>AppBuilder::schedule</code> runs periodic work every N seconds or on a cron (UTC), as queue jobs or in the process. <ul><li>Each slot runs once across all instances, with or without Redis, and <code>.without_overlapping()</code> is available.</li><li>Only <code>serve</code> runs schedules; <code>schedule:list</code> and <code>schedule:run</code> (<a href="./digging-deeper/scheduling.html">Scheduling</a>).</li></ul></li></ul><h2 id="040" tabindex="-1">0.4.0 <a class="header-anchor" href="#040" aria-label="Permalink to &quot;0.4.0&quot;">​</a></h2><ul><li><strong>Admin routes</strong>: JSON routes for your own panel pages under <code>{admin}/api/x</code>, on the admin session, each with a declared <code>AdminAccess</code> checked before extractors (<code>AdminRoutes</code>, <code>AuthProvider::admin_permissions</code>); <code>assert_access</code> tests every route against a table of actors (<a href="./admin/admin-routes.html">Admin routes</a>).</li><li><strong>Server-sent events</strong>: <code>AdminRoutes::events</code> streams live data to a page. <ul><li>It is rechecked while open: the session, the user, the permissions and a per-target check.</li><li>Limits are per user and per instance, slow clients are dropped, and streams end cleanly on shutdown.</li><li>A process-local <code>Hub</code> shares one producer between viewers, with <code>resync</code> when a viewer falls behind.</li><li>Script pages read streams with <code>ctx.realtime.events</code> (<a href="./admin/realtime.html">Realtime</a>).</li></ul></li><li><strong>WebSocket</strong>: <code>AdminRoutes::socket</code> for terminals and consoles. <ul><li>Admission: the exact <code>Origin</code> and the session&#39;s CSRF token as a subprotocol.</li><li>A supervised, rechecked socket with bounded queues both ways.</li><li><code>AdminSocket::authorize()</code> checks a command when it runs.</li><li>Script pages use <code>ctx.realtime.socket</code> (<a href="./admin/realtime.html#websocket">Realtime</a>).</li></ul></li><li><strong>Content Security Policy</strong>: unchanged, except that <code>connect-src</code> also names the panel&#39;s own <code>ws(s)://</code> origins.</li><li><strong>Secrets from files</strong>: every variable also reads <code>&lt;VAR&gt;_FILE</code> (Docker and Kubernetes secrets) (<a href="./getting-started/configuration.html">Configuration</a>).</li><li><strong>Testing</strong>: <code>TestApp::new</code> takes a closure, so tests can bind doubles. <code>RUSTCMS_TEST_BACKENDS</code> picks the databases, and <code>TestClient::socket</code> opens WebSocket connections (<a href="./basics/testing.html">Testing</a>).</li><li><strong>Tooling</strong>: the test servers run in memory (the matrix is about twice as fast), and <code>just test-fast</code> runs every test on SQLite only.</li></ul><h2 id="032" tabindex="-1">0.3.2 <a class="header-anchor" href="#032" aria-label="Permalink to &quot;0.3.2&quot;">​</a></h2><ul><li>The command checks and updates itself and applications: <code>rustcms doctor</code>, <code>rustcms upgrade [--dry-run]</code> (Core tag, SeaORM pins; comments and features kept), <code>rustcms self-update</code>, and <code>rustcms docs</code> (the guide, offline in release builds) (<a href="./upgrade.html#upgrading-the-command-and-an-application">Upgrading</a>).</li><li><code>make:command</code> refuses the names of the command&#39;s own commands.</li></ul><h2 id="031" tabindex="-1">0.3.1 <a class="header-anchor" href="#031" aria-label="Permalink to &quot;0.3.1&quot;">​</a></h2><ul><li><strong>Distribution</strong>: each tag publishes the <code>rustcms</code> command (macOS on Apple silicon, Linux x86_64 and arm64), the guide and <code>install.sh</code> (<a href="./getting-started/installation.html">Installation</a>).</li><li><code>rustcms new</code> depends on the RustCMS-Core Git tag of its version, writes a CI workflow (<code>.github/workflows/ci.yml</code>) and resolves dependencies (<code>--no-fetch</code> to skip).</li><li>Fixes: local storage on Linux (every upload, import and export failed with <code>Bad file descriptor</code>); migrations run on one connection; a refused TLS handshake is reported as <code>smtp_tls</code>; security updates of ammonia and rustls.</li></ul><h2 id="030" tabindex="-1">0.3.0 <a class="header-anchor" href="#030" aria-label="Permalink to &quot;0.3.0&quot;">​</a></h2><ul><li><strong>Admin panel</strong>: soft deletes with a trash; tabs and key/value inputs; media library, file uploads and rich text documents; has-many relation managers; custom field widgets from extension scripts; idempotent creates, actions and uploads (&quot;retry safely&quot;).</li><li><strong>Languages</strong>: the panel in English and Vietnamese, chosen per user; your labels translated from <code>lang/&lt;locale&gt;.toml</code> (<code>AdminProvider::translations</code>, <code>rustcms lang:missing</code>); validation errors carry stable codes (<a href="./admin/i18n.html">i18n</a>, <a href="./reference/error-codes.html">error codes</a>).</li><li><strong>Audit log</strong>: every admin write, upload, role and user change and API token recorded with its actor, credential and request, in the write&#39;s transaction; sign-ins, sign-outs and JWT events recorded best effort; redacted by declaration; <code>audit:prune</code> and hourly retention; shown to auditors in the panel, and as each record&#39;s history (<a href="./digging-deeper/audit-log.html">Audit log</a>).</li><li><strong>Settings</strong>: groups of settings as Rust structs, edited in the panel (<code>settings.&lt;group&gt;.view</code> / <code>.update</code>), read with <code>rustcms::settings::get</code>; secrets encrypted and never sent to the browser (<a href="./admin/settings.html">Settings</a>).</li><li><strong>Queues</strong>: jobs stored in the database, dispatched in the transaction of the change, run by workers in <code>serve</code> or <code>queue:work</code> with leases, retries, timeouts and graceful shutdown; <code>queue:failed</code> / <code>retry</code> / <code>forget</code>; a <strong>Queue page</strong> in the panel (System → Queue: jobs by status, retry, forget, cancel; <code>queue.view</code> / <code>queue.manage</code>) (<a href="./digging-deeper/queues.html">Queues</a>).</li><li><strong>Application layout</strong>: Laravel&#39;s folders inside <code>src/</code> (bootstrap, providers, routes, http controllers/requests/resources, services, jobs, settings, admin resources/pages, database migrations/seeders/factories); seeders and <code>db:seed</code>, factories, generators for each (<a href="./getting-started/directory-structure.html">Directory structure</a>; moving an existing app: <a href="./upgrade.html#application-layout-03">upgrade guide</a>).</li><li><strong>Parent locks</strong>: <code>ResourceMeta::lock_parent</code> for rules over a parent&#39;s children (<a href="./admin/resources.html#parent-locks">Resources</a>).</li><li><strong>Customizing the panel</strong>: a theme (color tokens, radius, fonts, logo, favicon, light/dark), custom pages and slots beside records from server templates (escaped, then sanitized) or extension scripts, custom table cells, <code>make:page</code>; <code>view!(&quot;file.html&quot;)</code> embeds a template and reads it again at each request in local development (<a href="./admin/customizing.html">Customizing</a>).</li><li><strong>Belongs-to-many relations</strong>: <code>Relation::belongs_to_many</code> through a pivot table, with pivot columns; attach, detach and edit links on a record&#39;s page, each with its own permission (<a href="./admin/relationships.html#belongs-to-many-pivot-tables">Relationships</a>).</li><li><strong>Actions with a form</strong>: <code>Action::form(vec![ActionField::…])</code> asks for values in a dialog, checked on the server (<a href="./admin/actions.html#actions-with-a-form">Actions</a>).</li><li><strong>CSV import and export</strong>: <code>ResourceMeta::exportable()</code> (the list as shown, readable fields only, protected against spreadsheet formulas; large lists in the background, checked again at download) and <code>importable()</code> / <code>import_key()</code> (upload, check, import through the usual write paths, a receipt per row) (<a href="./admin/import-export.html">Import and export</a>).</li><li><strong>Mail</strong>: SMTP (the server set in Settings → Mail or the configuration, within the operator&#39;s <code>allowed_hosts</code>/<code>allowed_ports</code>, TLS required), templates per language, mails queued with the change (<code>send_later</code>) and retried on temporary failures, a test-mail button, <code>log</code> and <code>memory</code> drivers; failed queue jobs can fail at once (<code>Failure::permanent</code>) (<a href="./digging-deeper/mail.html">Mail</a>).</li><li><strong>Password resets, invitations, remember me</strong>: &quot;Forgot password?&quot; mails a one-time link (the same answer whether the account exists); administrators invite users who choose their own password; sign-in can be remembered for <code>remember_days</code> (<a href="./security/authentication.html">Authentication</a>).</li><li><strong>Dashboard widgets</strong>: counts (compared with the period before), charts per day, week or month, and the latest records of a resource, each with its own permission and computed as the list shows records (<a href="./admin/dashboard.html">Dashboard</a>).</li><li><strong>Example</strong>: <code>examples/lms</code>, a small LMS back office: seats under a lock, instructor scopes, a job per enrollment, news (categories, tags, scheduled articles), editor and viewer roles, lessons moved up and down, a dashboard, welcome mails and instructor invitations (<a href="./examples/lms.html">An LMS back office</a>).</li><li><strong>Operations</strong>: running the queue, retention, backup and restore, rotating <code>APP_KEY</code>, running mail (<a href="./operations/queue.html">Operations</a>); several instances with Redis (shared rate limits, periodic jobs mostly on one instance); S3-compatible storage tested against a real server, Cloudflare R2 setup, bounded bucket timeouts (<a href="./digging-deeper/storage.html">File storage</a>).</li><li><strong>Permission matrix</strong>: the role page lays resource permissions out as resource × ability (<a href="./admin/users-roles.html">Users and roles</a>).</li><li><strong>Databases</strong>: MySQL 8.4 alongside SQLite and PostgreSQL.</li><li><strong>APIs</strong>: <code>ApiRoutes</code> with declared access, <code>Validated&lt;T&gt;</code>, <code>Pagination</code>, <code>Throttle&lt;N&gt;</code>, <code>make:api</code>; JWT access tokens with rotating refresh tokens.</li></ul><h2 id="010-alpha0" tabindex="-1">0.1.0-alpha.0 <a class="header-anchor" href="#010-alpha0" aria-label="Permalink to &quot;0.1.0-alpha.0&quot;">​</a></h2><ul><li>Resources rendered as an admin panel: forms, tables, filters, actions, <code>belongs_to</code> relationships, field and record authorization, hooks.</li><li>Admin sessions with CSRF and origin checks; API tokens with abilities; roles and permissions per guard; users, roles and account pages.</li><li>Application layer: configuration, providers, container, HTTP stack, migrations, console and generators, testing kit.</li></ul><p>See the <a href="./upgrade.html">upgrade guide</a> when moving between versions.</p>',55)])])}const g=t(r,[["render",i]]);export{m as __pageData,g as default};
